<script setup>
import {computed,onBeforeUnmount,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {api} from '../services/accounting.js';
import {reportMoney as money,reportDate as date,downloadCsv} from '../services/report-format.js';
import {errorText} from '../locales/accounting.js';
import {corporateTaxErrors} from '../locales/corporate-tax.js';
import {installmentTaxErrors,installmentTaxRows as rowLabels} from '../locales/installment-tax.js';
import {corporateTaxRegimes} from '../../../shared/corporate-tax.js';
import {installmentPeriods,emptyInstallmentTaxInput} from '../../../shared/installment-tax.js';
import TaxTabs from '../components/TaxTabs.vue';
import EntryDetail from '../components/EntryDetail.vue';
import TaxJournalPdf from '../components/TaxJournalPdf.vue';
import '../assets/tax.css';
import '../assets/corporate-tax.css';
const {company,exercises,selectedExercise,selectedId,selectExercise}=useContext(),{can}=useAccess(),route=useRoute(),router=useRouter();
const filters=ref({year:'',period:'1'}),result=ref(null),input=ref(emptyInstallmentTaxInput()),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),unsaved=ref(false),entryId=ref(null),journalPdf=ref(null),search=ref(''),visible=ref(100);
let generation=0;
const current=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date()),currentYear=Number(current.slice(0,4)),currentMonth=Number(current.slice(5,7));
const years=computed(()=>selectedExercise.value?[...new Set([selectedExercise.value.start_date.slice(0,4),selectedExercise.value.end_date.slice(0,4)])]:[]);
const periods=computed(()=>installmentPeriods.filter(row=>{const cutoff=filters.value.year+'-'+row.cutoff;return selectedExercise.value&&cutoff>=selectedExercise.value.start_date&&cutoff<=selectedExercise.value.end_date;}));
const matches=computed(()=>result.value&&result.value.exercise.id===selectedExercise.value?.id&&String(result.value.period.year)===filters.value.year&&String(result.value.period.period)===filters.value.period);
const ready=computed(()=>matches.value&&!loading.value&&!busy.value),changed=computed(()=>result.value&&JSON.stringify(input.value)!==JSON.stringify(result.value.input)),canExport=computed(()=>ready.value&&!changed.value);
const errors={...corporateTaxErrors,...installmentTaxErrors},msg=cause=>errors[cause.code]||errorText(cause);
const query=()=>new URLSearchParams({...filters.value,exercise_id:selectedExercise.value.id});
const modelRows=computed(()=>result.value?.input.method==='40.2'?['01','03']:['04','05','06','07','08','13','44','14','45','46',result.value?.brackets.length>1?'19':'16',result.value?.brackets.length>1?'26':'18','27','28','30','32','33','34']);
const sourceRows=computed(()=>{const term=search.value.trim().toLocaleLowerCase('es-ES');return (result.value?.source.records||[]).filter(row=>!term||[row.code,row.description,row.account_description,String(row.number)].some(value=>value?.toLocaleLowerCase('es-ES').includes(term)));});
async function consult(){
 const ticket=++generation;loading.value=true;result.value=null;error.value='';notice.value='';entryId.value=null;journalPdf.value=null;unsaved.value=false;
 if(!selectedExercise.value||!periods.value.length){loading.value=false;return;}
 try{const data=await api('/tax/installments?'+query(),{timeoutMs:45000});if(ticket!==generation)return;result.value=data;input.value=structuredClone(data.input);await router.replace({query:{payment_year:filters.value.year,payment_period:filters.value.period}});}
 catch(cause){if(ticket===generation)error.value=msg(cause);}finally{if(ticket===generation)loading.value=false;}
}
async function calculate(save=false){
 if(!ready.value)return;const ticket=++generation;busy.value=true;error.value='';notice.value='';
 try{const data=await api('/tax/installments/'+(save?'draft':'preview')+'?'+query(),{method:save?'PUT':'POST',body:save?{version:result.value.draft.version,input:input.value}:input.value,timeoutMs:45000});if(ticket===generation){result.value=data;input.value=structuredClone(data.input);unsaved.value=!save;notice.value=save?'Borrador 202 guardado para esta empresa, ejercicio y período.':'Cálculo actualizado. Guarda el borrador para conservar los criterios.';}}
 catch(cause){if(ticket===generation)error.value=msg(cause);}finally{if(ticket===generation)busy.value=false;}
}
function methodChanged(){input.value.confirmed=false;input.value.reviewed_source_hash='';void calculate(false);}
function confirmReview(){input.value.reviewed_source_hash=input.value.confirmed?result.value.source_hash:'';}
function addAdjustment(){input.value.adjustments.push({id:crypto.randomUUID(),description:'',direction:'increase',kind:'permanent',amount:'0.00',source_key:'',fingerprint:''});}
function clearStale(){input.value.adjustments=input.value.adjustments.filter(row=>!result.value.annual_model?.stale_adjustments.includes(row.id));input.value.confirmed=false;input.value.reviewed_source_hash='';}
function yearChanged(){if(!periods.value.some(row=>row.id===filters.value.period))filters.value.period=periods.value[0]?.id||'';}
function exportCsv(proposal=false){
 const data=result.value,a=value=>({amount:value||'0.00'}),rows=[['Modelo 202 · Pagos fraccionados IS',data.provisional?'Borrador provisional':'Borrador revisado'],['Empresa',data.company.name,'NIF',data.company.tax_id||''],['Año',data.period.year,'Período',data.period.code],['Ejercicio contable',data.exercise.name,'Desde',data.period.from,'Hasta',data.period.to],['Modalidad','Artículo '+data.input.method+' LIS'],['INCN anterior',data.input.previous_turnover===null?'Pendiente':a(data.input.previous_turnover)],[]];
 if(proposal){rows.push(['Propuesta del pago · No registrada'],['Cuenta','Descripción','Debe','Haber']);for(const line of data.settlement_proposal.lines)rows.push([line.code,line.description,a(line.debit),a(line.credit)]);}
 else{rows.push(['Casilla','Concepto','Importe']);for(const box of modelRows.value)rows.push([box,rowLabels[box],a(data.boxes[box])]);rows.push([],['Base de referencia · Declaración vencida',data.input.reference_note],[],['Base del tramo','Tipo IS %','Porcentaje 202 %','Cuota']);for(const row of data.brackets)rows.push([a(row.base),row.tax_rate,row.rate,a(row.quota)]);rows.push([],['Ajuste','Sentido','Tipo','Importe']);for(const row of data.input.adjustments)rows.push([row.description,row.direction,row.kind,a(row.amount)]);rows.push([],['Fecha','Asiento','Cuenta','Concepto','Debe','Haber']);for(const row of data.source.records)rows.push([row.date,row.number,row.code,row.description,a(row.debit),a(row.credit)]);rows.push([],['Notas',data.input.notes]);for(const issue of data.issues)rows.push(['Revisión',errors[issue]||issue]);}
 downloadCsv((proposal?'propuesta-pago-202-':'modelo-202-')+data.period.year+'-'+data.period.code+'.csv',rows);
}
function print(){window.print();}
watch(()=>selectedExercise.value?.id,()=>{
 const proposed=String(Math.min(Number(selectedExercise.value?.end_date.slice(0,4)||currentYear),Math.max(currentYear,Number(selectedExercise.value?.start_date.slice(0,4)||currentYear))));
 filters.value.year=years.value.includes(String(route.query.payment_year))?String(route.query.payment_year):proposed;
 const requested=String(route.query.payment_period||(Number(filters.value.year)===currentYear?currentMonth<=4?1:currentMonth<=10?2:3:3));filters.value.period=periods.value.some(row=>row.id===requested)?requested:periods.value[0]?.id||'';void consult();
},{immediate:true});
watch(search,()=>visible.value=100);
onBeforeUnmount(()=>generation++);
</script>
<template>
 <div class="tax-page corporate-tax-page">
  <TaxTabs />
  <div class="page-heading tax-controls"><div><p class="eyebrow">{{ company?.name }}</p><h1>Pagos fraccionados de Sociedades</h1><p class="muted">Modelo 202 · Artículos 40.2 y 40.3 LIS</p></div><div class="actions"><button class="button" :disabled="!canExport" @click="exportCsv(false)">Descargar CSV</button><button class="button" :disabled="!canExport" @click="print">Imprimir / guardar PDF</button><a class="button" href="https://sede.agenciatributaria.gob.es/Sede/procedimientoini/GE00.shtml" target="_blank" rel="noopener noreferrer">Modelo 202 · AEAT ↗</a></div></div>
  <form class="filters tax-filters tax-controls" @submit.prevent="consult"><label>Ejercicio contable<select aria-label="Ejercicio del modelo 202" :value="selectedId" :disabled="loading||busy" @change="selectExercise($event.target.value)"><option v-for="exercise in exercises" :key="exercise.id" :value="exercise.id">{{ exercise.name }} · {{ exercise.status==='closed'?'Cerrado':'Abierto' }}</option></select></label><label>Año de presentación<select v-model="filters.year" aria-label="Año del modelo 202" :disabled="loading||busy" @change="yearChanged"><option v-for="year in years" :key="year" :value="year">{{ year }}</option></select></label><label>Pago fraccionado<select v-model="filters.period" aria-label="Período del modelo 202" :disabled="loading||busy"><option v-for="period in periods" :key="period.id" :value="period.id">{{ period.label }}</option></select></label><button class="button" :disabled="loading||busy||!selectedExercise||!periods.length">Consultar modelo 202</button></form>
  <p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="notice success-note tax-controls" role="status">{{ notice }}</p><p v-if="loading" role="status">Consultando el pago fraccionado…</p><p v-else-if="!selectedExercise||!periods.length" class="notice">Este ejercicio no contiene un cierre acumulado de marzo, septiembre o noviembre del año elegido.</p><p v-else-if="!matches" class="notice">Pulsa Consultar modelo 202 para cargar el período seleccionado.</p>
  <template v-if="matches">
   <section class="panel tax-settings tax-controls" @input="unsaved=true" @change="unsaved=true"><div class="tax-toolbar"><div><h2>Criterios del pago fraccionado</h2><p class="muted">{{ result.draft.version?'Borrador guardado · Versión '+result.draft.version:'Sin borrador guardado' }}</p></div><div class="actions"><span v-if="unsaved||changed" class="muted">Cambios sin guardar</span><button class="button" :disabled="!ready" @click="calculate(false)">Recalcular</button><button v-if="can('accounting_write')" class="button primary" :disabled="!ready" @click="calculate(true)">Guardar borrador 202</button></div></div>
    <fieldset class="is-fieldset" :disabled="!ready"><div class="is-fields"><label>Modalidad<select v-model="input.method" aria-label="Modalidad del modelo 202" @change="methodChanged"><option value="40.2">Artículo 40.2 · 18 % de la última declaración vencida</option><option value="40.3">Artículo 40.3 · Base imponible acumulada</option></select></label><label>INCN de los doce meses anteriores (€)<input v-model="input.previous_turnover" aria-label="INCN anterior del modelo 202" inputmode="decimal" placeholder="Pendiente de confirmar" /><small>Revisa el grupo mercantil y las reglas de cómputo aplicables.</small></label></div>
     <template v-if="input.method==='40.2'"><div class="is-fields"><label>Base del pago · Casilla 01 (€)<input v-model="input.reference_base" aria-label="Base del pago 202" inputmode="decimal" /><small>Cuota íntegra menos deducciones, bonificaciones y retenciones. Los pagos 202 anteriores no se restan a esta base.</small></label><label>Declaración utilizada como referencia<input v-model="input.reference_note" maxlength="500" placeholder="Modelo 200, ejercicio y justificante" aria-label="Declaración de referencia" /></label></div><p class="is-help">Usa la declaración cuyo plazo ya hubiera vencido el día 1 de abril, octubre o diciembre. En ejercicios naturales suele ser el IS de dos años antes para abril y el del año anterior para octubre y diciembre. Si el período base duró menos de un año, revisa la agregación legal de períodos anteriores hasta completar al menos 365 días.</p><label class="checkbox-label"><input v-model="input.reference_confirmed" type="checkbox" />He comprobado el período de referencia y la base en la declaración presentada, incluidos períodos cortos si corresponde.</label></template>
     <template v-else><p class="is-help">Contabilidad acumulada: {{ date(result.period.from) }} — {{ date(result.period.to) }}. Los límites y tipos se refieren al período fiscal iniciado en {{ result.period.annual.year }}.</p><label v-if="!result.required_method" class="checkbox-label"><input v-model="input.option_confirmed" type="checkbox" />La opción censal por la modalidad del artículo 40.3 está vigente.</label><div class="is-fields"><label>Tipo de entidad / régimen<select v-model="input.regime" aria-label="Régimen del modelo 202"><option v-for="(label,key) in corporateTaxRegimes" :key="key" :value="key">{{ label }}</option></select></label></div><label v-if="input.regime==='small'" class="checkbox-label"><input v-model="input.erd_extension" type="checkbox" />Cumple la prórroga legal de entidad de reducida dimensión.</label><label v-if="input.regime==='new'" class="checkbox-label"><input v-model="input.new_entity_eligible" type="checkbox" />Cumple los requisitos y período de aplicación del tipo del 15 % de nueva creación.</label><label v-if="input.regime!=='patrimonial'" class="checkbox-label"><input v-model="input.new_loss_exception" type="checkbox" />Nueva creación: cumple la excepción de BIN en los tres primeros períodos con base positiva.</label>
      <h3>Ajustes fiscales acumulados</h3><p class="is-help">El IS contabilizado se corrige automáticamente. Añade los otros ajustes correspondientes a las fechas de este pago.</p><div v-if="input.adjustments.length" class="table-wrap"><table class="is-adjustments"><thead><tr><th>Concepto</th><th>Sentido</th><th>Tipo</th><th>Importe (€)</th><th></th></tr></thead><tbody><tr v-for="(row,index) in input.adjustments" :key="row.id"><td><input v-model="row.description" :aria-label="'Concepto ajuste 202 '+(index+1)" maxlength="200" /></td><td><select v-model="row.direction" :aria-label="'Sentido ajuste 202 '+(index+1)"><option value="increase">Aumento</option><option value="decrease">Disminución</option></select></td><td><select v-model="row.kind" :aria-label="'Tipo ajuste 202 '+(index+1)"><option value="permanent">Permanente</option><option value="temporary">Temporario</option></select></td><td><input v-model="row.amount" :aria-label="'Importe ajuste 202 '+(index+1)" inputmode="decimal" /></td><td><button class="button small" @click="input.adjustments.splice(index,1)">Eliminar</button></td></tr></tbody></table></div><div class="actions"><button class="button small" @click="addAdjustment">Añadir ajuste 202</button><button v-if="result.annual_model?.stale_adjustments.length" class="button small" @click="clearStale">Retirar ajustes con origen modificado</button></div>
      <div class="is-fields"><label>Capitalización pendiente de años anteriores (€)<input v-model="input.capitalization" inputmode="decimal" /><small>Casilla 44 · Solo remanente pendiente. La reserva del año en curso se revisa en el modelo 200.</small></label><label>BIN anteriores disponibles (€)<input v-model="input.losses_available" inputmode="decimal" /></label><label>Compensación de BIN<select v-model="input.losses_mode"><option value="none">Sin compensar</option><option value="maximum">Máximo permitido</option><option value="manual">Importe manual</option></select></label><label v-if="input.losses_mode==='manual'">BIN a compensar (€)<input v-model="input.losses_requested" inputmode="decimal" /></label><label>Nivelación · Aumento (€)<input v-model="input.leveling_increase" inputmode="decimal" /></label><label>Nivelación · Reducción (€)<input v-model="input.leveling_decrease" inputmode="decimal" /></label></div>
      <h3>Minoraciones comprobadas</h3><div class="is-fields"><label>Bonificaciones aplicables acumuladas (€)<input v-model="input.bonuses" inputmode="decimal" /></label><label>Retenciones e ingresos a cuenta acumulados (€)<input v-model="input.withholdings" aria-label="Retenciones acumuladas 202" inputmode="decimal" /></label><label>Pagos 202 anteriores efectivamente ingresados (€)<input v-model="input.previous_payments" aria-label="Pagos anteriores 202" inputmode="decimal" /></label></div><p class="is-help">Los pagos anteriores deben corresponder al mismo período impositivo. Los borradores guardados y el saldo global de 473 pueden incluir importes sin pagar u otros impuestos: comprueba los justificantes antes de deducirlos.</p><p v-if="result.previous_drafts.length" class="is-help">Borradores anteriores de este ejercicio: {{ result.previous_drafts.map(row=>row.year+' · '+row.period+'/P').join(', ') }}. Su existencia no acredita el ingreso.</p>
     </template>
     <label class="checkbox-label"><input v-model="input.consolidated" type="checkbox" />Consolidación fiscal · Requiere modelo 222.</label><label class="checkbox-label"><input v-model="input.special_scope" type="checkbox" />Hay normativa foral, exenciones, régimen especial u otros ajustes que requieren preparación específica.</label><label class="is-notes">Notas<textarea v-model="input.notes" rows="2" maxlength="2000"></textarea></label><label class="checkbox-label"><input v-model="input.confirmed" type="checkbox" @change="confirmReview" />He revisado la modalidad, la base y los importes. Corresponde un pago ordinario de territorio común y, si procede, el mínimo del 23 % sin exclusiones adicionales.</label>
    </fieldset>
   </section>
   <p v-if="changed" class="notice tax-warning tax-controls">Hay cambios pendientes de calcular. Recalcula o guarda el borrador para actualizar los importes y las exportaciones.</p><div v-if="result.issues.length" class="notice tax-warning"><strong>Borrador provisional · Revisiones pendientes</strong><ul><li v-for="issue in result.issues" :key="issue">{{ errors[issue]||issue }}</li></ul></div>
   <section class="vat-model" aria-label="Borrador modelo 202"><header class="vat-model-heading"><div><p class="eyebrow">{{ result.provisional?'BORRADOR PROVISIONAL':'BORRADOR REVISADO' }}</p><h2>Pago fraccionado del IS</h2><p>{{ result.period.label }} de {{ result.period.year }} · Artículo {{ result.input.method }} LIS</p></div><div class="vat-model-number">Modelo<strong>202</strong></div></header><div class="vat-identification"><div><small>NIF</small><strong>{{ result.company.tax_id||'Pendiente' }}</strong></div><div><small>Razón social</small><strong>{{ result.company.name }}</strong></div><div><small>Año</small><strong>{{ result.period.year }}</strong></div><div><small>Período</small><strong>{{ result.period.code }}</strong></div></div><p class="vat-period">{{ result.input.method==='40.2'?'Base de la última declaración vencida · 18 %':'Contabilidad acumulada: '+date(result.period.from)+' — '+date(result.period.to) }}</p>
    <div class="vat-section"><h3>Liquidación del pago fraccionado</h3><div v-for="box in modelRows.filter(key=>!['03','34'].includes(key))" :key="box" class="vat-total"><span>{{ rowLabels[box] }}</span><div class="vat-static-box"><small>{{ box }}</small><strong>{{ money(result.boxes[box]) }}</strong></div></div><div v-if="result.brackets.length" class="is-rate-detail"><p v-for="(row,index) in result.brackets" :key="index">{{ money(row.base) }} € × {{ row.rate.replace('.',',') }} % = {{ money(row.quota) }} € <span class="muted">(tipo IS {{ row.tax_rate.replaceAll('.',',') }} %)</span></p></div><p v-if="result.input.method==='40.3'&&result.summary.minimum!=='0.00'" class="is-help">El mínimo se calcula sobre el resultado contable positivo después del IS y se resta únicamente el pago fraccionado anterior ingresado. Se aplica el mayor entre resultado ordinario y mínimo.</p><div class="vat-total vat-result"><div><strong>{{ result.result==='0.00'?'Sin importe a ingresar':'Cantidad a ingresar' }}</strong><p>{{ result.provisional?'Pendiente de revisión':'Borrador revisado' }}</p></div><div class="vat-static-box" data-installment-result><small>{{ result.input.method==='40.2'?'03':'34' }}</small><strong>{{ money(result.result) }} €</strong></div></div><p class="is-help">{{ result.mandatory===null?'Confirma la cifra de negocios para revisar la obligación.':result.mandatory?'Corresponde presentar en el supuesto ordinario calculado.':'Sin ingreso ni obligación de presentar en el supuesto ordinario calculado.' }}</p></div>
    <footer class="vat-model-footer"><strong>DOCUMENTO DE TRABAJO · NO PRESENTADO</strong><p>CSV y PDF preparan el pago. La declaración se completa y presenta en la sede de la AEAT; este borrador no acredita presentación ni ingreso.</p><p><a href="https://sede.agenciatributaria.gob.es/Sede/todas-gestiones/impuestos-tasas/impuesto-sobre-sociedades/modelo-202-is-i_____resencia-territorio-fraccionado_/instrucciones.html" target="_blank" rel="noopener noreferrer">Instrucciones del modelo 202 · AEAT</a></p></footer>
   </section>
   <details v-if="result.settlement_proposal.lines.length" class="panel tax-settings" open><summary><strong>Propuesta contable del pago</strong></summary><p class="is-help">Registra el pago en su fecha real y con la subcuenta 473 y el banco correspondientes. El borrador no crea un movimiento bancario.</p><div class="table-wrap"><table><thead><tr><th>Cuenta</th><th>Descripción</th><th class="amount">Debe</th><th class="amount">Haber</th></tr></thead><tbody><tr v-for="(row,index) in result.settlement_proposal.lines" :key="index"><td>{{ row.code }}</td><td>{{ row.description }}</td><td class="amount">{{ money(row.debit) }}</td><td class="amount">{{ money(row.credit) }}</td></tr></tbody></table></div><div class="actions tax-controls"><button class="button" :disabled="!canExport" @click="exportCsv(true)">CSV del pago propuesto</button><RouterLink class="button" to="/asientos">Ir a Asientos</RouterLink></div></details>
   <section v-if="result.input.method==='40.3'" class="panel tax-settings tax-controls" aria-label="Origen contable del modelo 202"><div class="tax-detail-heading"><div><h2>Origen contable del acumulado</h2><p class="muted">{{ sourceRows.length }} movimientos · {{ date(result.period.from) }} — {{ date(result.period.to) }}</p></div><RouterLink class="button" to="/hacienda/sociedades">Ver modelo 200</RouterLink></div><label class="is-notes">Buscar movimiento<input v-model="search" type="search" placeholder="Cuenta, concepto o asiento" /></label><div class="table-wrap"><table><thead><tr><th>Fecha / asiento</th><th>Cuenta</th><th>Concepto</th><th class="amount">Debe</th><th class="amount">Haber</th><th></th></tr></thead><tbody><tr v-for="row in sourceRows.slice(0,visible)" :key="row.key"><td>{{ date(row.date) }}<br /><button class="button small" @click="entryId=row.entry_id">Asiento {{ row.number }}</button></td><td>{{ row.code }}<small>{{ row.account_description }}</small></td><td>{{ row.description }}</td><td class="amount">{{ money(row.debit) }}</td><td class="amount">{{ money(row.credit) }}</td><td><button v-if="row.source_available" class="button small" @click="journalPdf={entryId:row.entry_id,page:row.source_page}">Diario PDF</button></td></tr><tr v-if="!sourceRows.length"><td colspan="6">Sin movimientos en este acumulado.</td></tr></tbody></table></div><button v-if="sourceRows.length>visible" class="button" @click="visible+=100">Mostrar 100 más</button><p v-if="result.source.diagnostic?.unbalanced.length" class="notice error-notice">Asientos descuadrados: {{ result.source.diagnostic.unbalanced.map(row=>row.number).join(', ') }}</p><p v-if="result.source.diagnostic?.unclassified.length" class="notice">Cuentas sin clasificar: {{ result.source.diagnostic.unclassified.map(row=>row.code).join(', ') }}</p></section>
  </template>
  <EntryDetail v-if="entryId" :entry-id="entryId" @close="entryId=null" /><TaxJournalPdf v-if="journalPdf" :entry-id="journalPdf.entryId" :page="journalPdf.page" title="Diario original · Modelo 202" @close="journalPdf=null" />
 </div>
</template>
